CustomField.formula:
IF( MOD(CEILING((End_Date__c - Start_Date__c) / 30.5) ,12)<=2 , FLOOR((CEILING((End_Date__c - Start_Date__c) / 30.5) /12)), IF( ( MOD(CEILING((End_Date__c - Start_Date__c) / 30.5) ,12)>=3 && MOD(CEILING((End_Date__c - Start_Date__c) / 30.5) ,12)<=8 ), FLOOR((CEILING((End_Date__c - Start_Date__c) / 30.5) /12)) + 0.5,
FLOOR((CEILING((End_Date__c - Start_Date__c) / 30.5) /12)) + 1 )
)
